  "oneOf": [
    {
      "type": "object",
      "required": ["type", "text"],
      "additionalProperties": false,
      "properties": {
        "type": {"const": "send_message"},
        "text": {"type": "string", "minLength": 1, "maxLength": 1000}
      }
    },
    {
      "type": "object",
      "required": ["type"],
      "additionalProperties": false,
      "properties": {"type": {"const": "no_message"}}
    }
  ]
}


